/*
 * A274500  The odd integers in the sequence appear in blocks and the
 *          successive sizes of these blocks are given by the sequence itself.
 * https://oeis.org/A274500
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, base
 * Formula:   The sequence is generated by blocks of odd integers whose sizes
 *            are the sequence itself. Each block consists of a(i) consecutive
 *            odd integers followed immediately by a(i) consecutive even
 *            integers. The odds and evens are the natural numbers in
 *            increasing order without repetition
 * Range:     u8 n <= 251, u16 n <= 10000, u32 n <= 10000, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>

seq_t a(idx_t n)
{
    if (n < 1)
        return 0;

    size_t len = (size_t)n;
    seq_t *arr = (seq_t *)malloc((len + 1) * sizeof(seq_t));
    if (!arr)
        return 0;                 /* allocation failure – delegate to caller */

    seq_t odd_next  = (seq_t)1;    /* next unused odd number     */
    seq_t even_next = (seq_t)2;    /* next unused even number    */
    size_t pos  = 1;              /* position of next term       */
    size_t blk  = 1;              /* block index                 */

    /* ---- block 1 (size = a(1) = 1) ------------------------------------- */
    arr[1] = odd_next;            /* a(1) = 1 (odd)              */
    odd_next += (seq_t)2;
    pos++;

    seq_t bs = arr[1];            /* block size of block 1       */
    for (seq_t i = 0; i < bs && pos <= len; ++i) {
        arr[pos] = even_next;     /* a(2) = 2 (even)             */
        even_next += (seq_t)2;
        pos++;
    }
    blk++;                        /* next block index            */

    /* ---- subsequent blocks --------------------------------------------- */
    while (pos <= len) {
        bs = arr[blk];            /* size of current block       */
        /* odd part of the block */
        for (seq_t i = 0; i < bs && pos <= len; ++i) {
            arr[pos] = odd_next;
            odd_next += (seq_t)2;
            pos++;
        }
        /* even part of the block */
        for (seq_t i = 0; i < bs && pos <= len; ++i) {
            arr[pos] = even_next;
            even_next += (seq_t)2;
            pos++;
        }
        blk++;                    /* proceed to the next block  */
    }

    seq_t result = arr[len];
    free(arr);
    return result;
}
